def transition(p,status,sync=False,settled=None):
 p.get_by_label('Requested transaction status',exact=True).select_option(status);p.get_by_label('Transition reason',exact=True).fill('Isolated owner demonstration')
 if sync:p.get_by_label('Also record the corresponding inventory status.',exact=False).check()
